async function renderAPIBreakdown(startDate, endDate) {
    const authToken = localStorage.getItem('authToken');
    if (!authToken) {
        window.location.href = 'login.html';
        return;
    }

    try {
        const response = await fetch(`${API_BASE_URL}/dashboard/api-usage/breakdown?start_date=${startDate}&end_date=${endDate}`, {
            method: 'GET',
            headers: {
                'Authorization': `Bearer ${authToken}`,
            }
        });

        const breakdownData = await response.json();
        console.log(breakdownData);

        const tableBody = document.getElementById("api-breakdown-body");
        tableBody.innerHTML = "";

        breakdownData.breakdown.forEach(item => {
            const row = document.createElement("tr");

            // Page name
            const pageCell = document.createElement("td");
            pageCell.textContent = item.page.charAt(0).toUpperCase() + item.page.slice(1);
            row.appendChild(pageCell);

            // Call count
            const countCell = document.createElement("td");
            countCell.textContent = item.count;
            row.appendChild(countCell);

            // Percentage
            const percentCell = document.createElement("td");
            percentCell.textContent = `${item.percentage}%`;
            row.appendChild(percentCell);

            // Visual bar
            const barCell = document.createElement("td");
            const barContainer = document.createElement("div");
            barContainer.className = "bar-container";

            const bar = document.createElement("div");
            bar.className = "bar-fill";
            bar.style.width = `${item.percentage}%`;

            barContainer.appendChild(bar);
            barCell.appendChild(barContainer);
            row.appendChild(barCell);

            tableBody.appendChild(row);
        });

    } catch (error) {
        console.log('Error fetching API breakdown data:', error);
    }
}
// ...existing code...
